-- Supplier Certification Expiry Alerts — Complete Schema
create extension if not exists "pgcrypto";
create table organizations (id uuid primary key default gen_random_uuid(), name text not null, industry_vertical text not null default 'food_beverage', subscription_plan text not null default 'core' check (subscription_plan in ('core', 'full_suite')), subscription_status text not null default 'trialing' check (subscription_status in ('trialing', 'active', 'past_due', 'canceled')), mor_customer_id text, intake_email text, created_at timestamptz not null default now());
create table users (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, email text not null unique, name text, role text not null default 'member' check (role in ('admin', 'member')), clerk_user_id text unique, created_at timestamptz not null default now());
create table suppliers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, name text not null, contact_name text, contact_email text, created_at timestamptz not null default now());
create table certificates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid not null references suppliers(id) on delete cascade, certificate_type text not null, issuing_body text, certificate_number text, issue_date date, expiry_date date not null, status text not null default 'valid' check (status in ('valid', 'expiring_soon', 'expired')), file_url text, extraction_source text not null default 'manual' check (extraction_source in ('manual', 'ai_extracted')), extraction_confidence numeric(3,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index idx_certificates_expiry on certificates (expiry_date);
create index idx_certificates_org on certificates (organization_id);
create table alert_rules (id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id) on delete cascade, name text not null default 'Alert', days_before_expiry int not null, recipient_email text not null, is_active boolean not null default true, enabled boolean not null default true, created_at timestamptz not null default now());
create table alerts_sent (id uuid primary key default gen_random_uuid(), certificate_id uuid not null references certificates(id) on delete cascade, days_before_expiry int not null, recipient_email text not null, sent_at timestamptz not null default now(), unique (certificate_id, days_before_expiry));
create table certificate_uploads (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid references suppliers(id) on delete set null, uploaded_by uuid references users(id), file_url text not null, file_name text, file_type text, file_key text, extracted_data jsonb, raw_extraction jsonb, confidence text, status text not null default 'pending_review' check (status in ('pending', 'pending_review', 'confirmed', 'rejected')), confirmed_certificate_id uuid references certificates(id), reviewed_at timestamptz, created_at timestamptz not null default now());
insert into alert_rules (organization_id, days_before_expiry, enabled) values (null, 90, true), (null, 60, true), (null, 30, true), (null, 7, true);
alter table suppliers enable row level security;
alter table certificates enable row level security;
alter table certificate_uploads enable row level security;
alter table alert_rules enable row level security;
create policy tenant_isolation_suppliers on suppliers using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create policy tenant_isolation_certificates on certificates using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create policy tenant_isolation_certificate_uploads on certificate_uploads using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create policy tenant_isolation_alert_rules on alert_rules using (organization_id = current_setting('app.current_org_id')::uuid or organization_id is null);
create table inbox_messages (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid references suppliers(id) on delete set null, from_email text not null, subject text, body_preview text, attachment_url text, status text not null default 'pending' check (status in ('pending', 'processing', 'linked_upload', 'dismissed')), certificate_upload_id uuid references certificate_uploads(id) on delete set null, created_at timestamptz not null default now());
alter table inbox_messages enable row level security;
create policy tenant_isolation_inbox on inbox_messages using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create table onboarding_requests (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid references suppliers(id) on delete set null, supplier_name text not null, contact_email text, status text not null default 'draft' check (status in ('draft', 'sent', 'submitted', 'approved', 'rejected')), form_payload jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table onboarding_requests enable row level security;
create policy tenant_isolation_onboarding on onboarding_requests using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create table supplier_audits (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid not null references suppliers(id) on delete cascade, audit_type text not null default 'supplier', scheduled_date date, completed_date date, outcome text check (outcome is null or outcome in ('pass', 'pass_with_capa', 'fail', 'pending')), notes text, created_at timestamptz not null default now());
create table capa_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, audit_id uuid not null references supplier_audits(id) on delete cascade, title text not null, due_date date, status text not null default 'open' check (status in ('open', 'in_progress', 'closed')), created_at timestamptz not null default now());
alter table supplier_audits enable row level security;
alter table capa_items enable row level security;
create policy tenant_isolation_audits on supplier_audits using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create policy tenant_isolation_capa on capa_items using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create table supplier_risk_scores (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid not null references suppliers(id) on delete cascade, score numeric(5,2) not null, band text not null check (band in ('low', 'medium', 'high', 'critical')), factors jsonb not null default '{}', computed_at timestamptz not null default now(), unique (organization_id, supplier_id));
alter table supplier_risk_scores enable row level security;
create policy tenant_isolation_risk on supplier_risk_scores using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
create table supplier_tiers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, parent_supplier_id uuid not null references suppliers(id) on delete cascade, child_supplier_id uuid not null references suppliers(id) on delete cascade, relationship text not null default 'sub_supplier', material_name text, origin_country text, created_at timestamptz not null default now(), unique (organization_id, parent_supplier_id, child_supplier_id, relationship));
alter table supplier_tiers enable row level security;
create policy tenant_isolation_tiers on supplier_tiers using (organization_id = current_setting('app.current_org_id')::uuid) with check (organization_id = current_setting('app.current_org_id')::uuid);
